companies = boundary retry 3 {
  return list_companies({})
} catch err {
  return fail("COMPANIES", err.message)
}
by_domain = fold acc = {} for c in companies {
  return acc + { [c.domain]: c.name }
}
first = boundary retry 3 {
  return list_contacts({ page: 1 })
} catch err {
  return fail("LIST", err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
  result = boundary retry 3 {
    return list_contacts({ page: page })
  } catch err {
    return fail("LIST", err.message)
  }
  return result.items
}
all = fold acc = first.items for page_items in remaining {
  return acc + page_items
}
results = for contact in all {
  phone = contact.phone if contact.phone != null else ""
  already_valid = regex.test(phone, "^\\+1[0-9]{10}$")
  digits = regex.replace(phone, "[^0-9]", "")
  e164 = if already_valid {
    return phone
  } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
    return "+" + digits
  } else if text.length(digits) == 10 {
    return "+1" + digits
  } else if text.length(digits) > 0 {
    return "+1" + digits
  } else {
    return phone
  }
  phone_needs = not already_valid and e164 != phone and e164 != ""
  email = contact.email if contact.email != null else ""
  parts = text.split(email, "@")
  domain = parts[1] if list.length(parts) >= 2 else ""
  company_empty = contact.company == null or contact.company == ""
  new_company = by_domain[domain] if company_empty and domain != "" and domain in by_domain else null
  company_needs = new_company != null
  skip if not phone_needs and not company_needs
  _ = boundary retry 3 {
    return update_contact({
      id: contact.id,
      phone: e164 if phone_needs else null,
      company: new_company if company_needs else null
    })
  } catch err {
    return fail("UPDATE", err.message)
  }
  return {
    phone_fixed: phone_needs,
    company_filled: company_needs
  }
}
phones_fixed = fold acc = 0 for r in results {
  return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
  return acc + (1 if r.company_filled else 0)
}
submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submitted }
